@e-schultz you can override the restrict to work with the component helper. Its just set to E by default

``` js
angular.module('something').component('home', {
    restrict: 'AE'
});
```

Ran into this problem with the latest build. All of my css is dependent on styling the actual component tags like <element></element> Until it's fixed, I just overloaded ngOutlet in my main app.js file. Not saying it's the right thing to do, but it definitely works...

``` javascript
app.directive('ngOutlet', function($compile) {
    return {
        restrict: 'EA',
        priority: -400,
        require: 'ngOutlet',
        link: function (scope, element, attrs, ctrl) {
            // The fix
            var dashName = ctrl.$$componentName.replace(/[A-Z]/g, function (match) { return '-' + match.toLowerCase(); });
            var template = ctrl.$$template = '<' + dashName + '></'+ dashName +'>';

            //copied out of the main angular_1_router.js file
            element.html(template);
            var link = $compile(element.contents());
            link(scope);
            var componentInstance = scope[ctrl.$$componentName];
            if (componentInstance) {
                ctrl.$$currentComponent = componentInstance;
                componentInstance.$router = ctrl.$$router;
                componentInstance.$routeParams = ctrl.$$routeParams;
            }
        }
    };
});
```

Using Angular 1.5rc2 you can not override `restrict` on component creation, this is the `.component` code:

``` javascript
this.component = function registerComponent(name, options) {
    var controller = options.controller || function() {};

    function factory($injector) {
      function makeInjectable(fn) {
        if (isFunction(fn) || isArray(fn)) {
          return function(tElement, tAttrs) {
            return $injector.invoke(fn, this, {$element: tElement, $attrs: tAttrs});
          };
        } else {
          return fn;
        }
      }

      var template = (!options.template && !options.templateUrl ? '' : options.template);
      return {
        controller: controller,
        controllerAs: identifierForController(options.controller) || options.controllerAs || '$ctrl',
        template: makeInjectable(template),
        templateUrl: makeInjectable(options.templateUrl),
        transclude: options.transclude,
        scope: {},
        bindToController: options.bindings || {},
        restrict: 'E', // <== HERE
        require: options.require
      };
    }

    // Copy any annotation properties (starting with $) over to the factory function
    // These could be used by libraries such as the new component router
    forEach(options, function(val, key) {
      if (key.charAt(0) === '$') {
        factory[key] = val;
      }
    });

    factory.$inject = ['$injector'];

    return this.directive(name, factory);
  }
```

And I think this is correct, I think you have to change the ngComponentRouter code.
